import type { FC } from 'react';
import { useState } from 'react';
import { Share2, Check } from 'lucide-react';
import { toast } from 'sonner';

interface ShareButtonProps {
  getUrl: () => string;
  disabled?: boolean;
  className?: string;
}

// Copies a link that reproduces just this result for whoever opens it — see
// src/components/share/ShareLayout.tsx for what they land on.
const ShareButton: FC<ShareButtonProps> = ({ getUrl, disabled, className }) => {
  const [copied, setCopied] = useState(false);

  const handleShare = async () => {
    try {
      await navigator.clipboard.writeText(getUrl());
      setCopied(true);
      toast.success('Share link copied');
      window.setTimeout(() => setCopied(false), 1500);
    } catch {
      toast.error('Copy failed');
    }
  };

  return (
    <button
      type="button"
      disabled={disabled}
      onClick={handleShare}
      className={
        className ??
        'inline-flex items-center justify-center gap-2 px-4 py-2.5 rounded-lg text-sm font-medium border border-border text-foreground/80 hover:text-foreground hover:border-accent/40 transition-colors disabled:opacity-40 disabled:cursor-not-allowed'
      }
    >
      {copied ? <Check className="w-4 h-4 text-accent" /> : <Share2 className="w-4 h-4" />}
      {copied ? 'Copied' : 'Share result'}
    </button>
  );
};

export default ShareButton;
